{"tool":"submit_job","args":{"source":"import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

export async function gate({ referenceDir, submissionDir }) {
  const pinnedPath = path.join(referenceDir, "pinned-test-cases.txt");
  let pinnedSource;
  try {
    pinnedSource = fs.readFileSync(pinnedPath, "utf8");
  } catch (err) {
    return { accept: false, reason: `Could not read pinned test cases: ${err.message}` };
  }

  const answerPath = path.join(submissionDir, "answer.mjs");
  if (!fs.existsSync(answerPath)) {
    return { accept: false, reason: "submission missing answer.mjs" };
  }
  const answerUrl = pathToFileURL(answerPath).href;

  // Count how many pinned test cases we expect to see run, by counting
  // top-level test(...) invocations in the pinned source text.
  const expectedCountMatches = pinnedSource.match(/\btest\s*\(/g) || [];
  const expectedCount = expectedCountMatches.length;

  const uniqueTag = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const combinedPath = path.join(referenceDir, `combined-test-${uniqueTag}.mjs`);

  const combinedSource = [
    'import test from "node:test";',
    'import assert from "node:assert/strict";',
    `import { dedupeSorted } from ${JSON.stringify(answerUrl)};`,
    "",
    pinnedSource,
    "",
  ].join("\n");

  try {
    fs.writeFileSync(combinedPath, combinedSource, "utf8");
  } catch (err) {
    return { accept: false, reason: `Could not write combined test file: ${err.message}` };
  }

  let result;
  try {
    result = spawnSync(process.execPath, [combinedPath], {
      timeout: 15000,
      encoding: "utf8",
      maxBuffer: 10 * 1024 * 1024,
      env: { ...process.env },
    });
  } finally {
    try { fs.unlinkSync(combinedPath); } catch (_) {}
  }

  if (result.error) {
    return { accept: false, reason: `Failed to execute test process: ${result.error.message}` };
  }

  const stdout = result.stdout || "";
  const stderr = result.stderr || "";

  if (result.signal) {
    return {
      accept: false,
      reason: `Test process terminated by signal ${result.signal} (possible timeout, crash, or resource abuse). stdout:\n${stdout.slice(-1500)}\nstderr:\n${stderr.slice(-1500)}`,
    };
  }

  // Do not trust the raw process exit code alone: a malicious submission could
  // hijack process.exit / process.exitCode from within its own module scope to
  // force a code-0 exit regardless of actual test outcomes (including exiting
  // before any test() calls even run). Instead, independently parse node:test's
  // own TAP summary lines out of stdout and require them to be internally
  // consistent with the number of pinned test cases we actually asked it to run.
  const testsMatch = stdout.match(/^# tests (\d+)/m);
  const passMatch = stdout.match(/^# pass (\d+)/m);
  const failMatch = stdout.match(/^# fail (\d+)/m);

  if (!testsMatch || !passMatch || !failMatch) {
    return {
      accept: false,
      reason: `Could not find a complete TAP summary in test output (submission may have exited early or corrupted output). stdout:\n${stdout.slice(-2000)}\nstderr:\n${stderr.slice(-1500)}`,
    };
  }

  const testsRun = parseInt(testsMatch[1], 10);
  const passed = parseInt(passMatch[1], 10);
  const failed = parseInt(failMatch[1], 10);

  // Also check for any explicit failing top-level TAP lines as a second signal.
  const notOkCount = (stdout.match(/^not ok /m) || []).length;

  if (expectedCount > 0 && testsRun !== expectedCount) {
    return {
      accept: false,
      reason: `Expected ${expectedCount} pinned test cases to run but TAP summary reports ${testsRun}. Possible early exit or tampering. stdout:\n${stdout.slice(-2000)}`,
    };
  }

  if (failed !== 0 || notOkCount !== 0 || result.status !== 0) {
    return {
      accept: false,
      reason: `Pinned tests did not all pass. tests=${testsRun} pass=${passed} fail=${failed} exitCode=${result.status}.\nstdout:\n${stdout.slice(-3000)}\nstderr:\n${stderr.slice(-1500)}`,
    };
  }

  if (passed !== expectedCount) {
    return {
      accept: false,
      reason: `TAP summary pass count (${passed}) does not match expected pinned test count (${expectedCount}).\nstdout:\n${stdout.slice(-2000)}`,
    };
  }

  return {
    accept: true,
    reason: `All ${expectedCount} pinned tests passed (tests=${testsRun} pass=${passed} fail=${failed}).`,
  };
}
